#!/bin/bash
# Provisions the temporary Samba test server. Runs as root inside the dedicated WSL distro
# "nexdir-samba-test" only (never in a distro you use otherwise).
#   wsl -d nexdir-samba-test -u root -- bash provision.sh /mnt/c/path/to/secrets-folder
# The secrets folder holds creds.json (generated by setup.ps1, git-ignored); this script reads
# the passwords from it and passes them to smbpasswd on stdin only.
set -euo pipefail
SEC="${1:?usage: provision.sh <secrets folder with creds.json>}"
grep -q '^ID=debian' /etc/os-release
HERE="$(cd "$(dirname "$0")" && pwd)"
systemctl stop smbd nmbd 2>/dev/null || true
pkill -x smbd 2>/dev/null || true
install -m 644 "$HERE/smb.conf" /etc/samba/smb.conf
getent group nxshare >/dev/null || groupadd nxshare
for u in nxtest nxprivate nxother; do
  id "$u" >/dev/null 2>&1 || useradd --no-create-home --shell /usr/sbin/nologin -G nxshare "$u"
done
# Passwords from the secrets file, passed on stdin only (never on a command line or in output).
for u in nxtest nxprivate nxother; do
  pw=$(python3 -c "import json,sys;print(json.load(open('$SEC/creds.json'))[sys.argv[1]])" "$u")
  printf '%s\n%s\n' "$pw" "$pw" | smbpasswd -a -s "$u" >/dev/null
  smbpasswd -e "$u" >/dev/null
done
unset pw
B=/srv/nexdir-test
mkdir -p $B/public $B/private $B/readonly $B/large
chown root:nxshare $B/public && chmod 2775 $B/public
chown nxprivate:nxprivate $B/private && chmod 0700 $B/private
chown nxtest:nxtest $B/large && chmod 0755 $B/large
# Synthetic data
echo "synthetic public file" > $B/public/hello.txt
mkdir -p "$B/public/Ünïcödé 日本 😀"
echo "unicode content" > "$B/public/Ünïcödé 日本 😀/Résumé 😀.txt"
echo "private synthetic data" > $B/private/secret-test.txt && chown nxprivate:nxprivate $B/private/secret-test.txt
mkdir -p $B/readonly/docs
for i in 1 2 3; do echo "read-only file $i" > $B/readonly/docs/file$i.txt; done
head -c 3145728 /dev/urandom > $B/readonly/random-3MiB.bin
chown -R root:root $B/readonly && chmod -R a+rX,go-w $B/readonly
chown -R root:nxshare $B/public && chmod -R g+rwX $B/public
testparm -s /etc/samba/smb.conf >/dev/null 2>&1 && echo testparm-ok
systemctl disable --now nmbd >/dev/null 2>&1 || true
systemctl restart smbd
ss -ltn | grep ':445'
